=== FILE: sync_fifo.v ===
`timescale 1ns/1ps
`default_nettype none
// sync_fifo: parameterizable synchronous FIFO, first-word fall-through.
// Implements interface_spec.md per microarchitecture.md:
//   - explicit occupancy counter (works for any DEPTH >= 2)
//   - pointers wrap by comparing against LAST = DEPTH-1
//   - write accepted when wr_en && !full, read when rd_en && !empty
//   - rd_data = mem[rd_ptr] (combinational, valid while !empty)
//   - synchronous active-low reset clears pointers and count; storage not reset
module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);
    localparam integer AW = $clog2(DEPTH);
    localparam integer CW = $clog2(DEPTH+1);
    localparam [AW-1:0] LAST     = DEPTH[AW-1:0] - 1'b1;
    localparam [CW-1:0] FULL_CNT = DEPTH[CW-1:0];

    reg [WIDTH-1:0] mem [0:DEPTH-1];
    reg [AW-1:0]    wr_ptr;
    reg [AW-1:0]    rd_ptr;
    reg [CW-1:0]    count_q;

    wire wr_acc = wr_en & ~full;
    wire rd_acc = rd_en & ~empty;

    assign full    = (count_q == FULL_CNT);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;
    assign rd_data = mem[rd_ptr];

    // Storage: datapath, not reset, written only outside reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr] <= wr_data;
        end
    end

    // Control: pointers and occupancy counter, synchronous reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= {AW{1'b0}};
            rd_ptr  <= {AW{1'b0}};
            count_q <= {CW{1'b0}};
        end else begin
            if (wr_acc) begin
                wr_ptr <= (wr_ptr == LAST) ? {AW{1'b0}} : wr_ptr + 1'b1;
            end
            if (rd_acc) begin
                rd_ptr <= (rd_ptr == LAST) ? {AW{1'b0}} : rd_ptr + 1'b1;
            end
            case ({wr_acc, rd_acc})
                2'b10:   count_q <= count_q + 1'b1;
                2'b01:   count_q <= count_q - 1'b1;
                default: count_q <= count_q;
            endcase
        end
    end

`ifdef FORMAL
    // Design-intent assertions (not run as part of this delivery).
    reg f_past_valid = 1'b0;
    initial assume (!rst_n);
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (f_past_valid) begin
            assert (!(full && empty));
            assert (count_q <= FULL_CNT);
            assert (wr_ptr <= LAST);
            assert (rd_ptr <= LAST);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (count_q == {CW{1'b0}});
                assert (wr_ptr == {AW{1'b0}});
                assert (rd_ptr == {AW{1'b0}});
            end else begin
                if ($past(wr_acc) && !$past(rd_acc))
                    assert (count_q == $past(count_q) + 1'b1);
                if (!$past(wr_acc) && $past(rd_acc))
                    assert (count_q == $past(count_q) - 1'b1);
                if ($past(wr_acc) == $past(rd_acc))
                    assert (count_q == $past(count_q));
                if ($past(wr_en) && $past(full))
                    assert (wr_ptr == $past(wr_ptr));
                if ($past(rd_en) && $past(empty))
                    assert (rd_ptr == $past(rd_ptr));
            end
        end
    end
`endif

endmodule
`default_nettype wire
=== END FILE ===
=== FILE: sync_fifo_tb.v ===
`timescale 1ns/1ps
// verilator lint_off WIDTH
// Self-checking testbench for sync_fifo.
// Two DUTs on the same stimulus: DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12,
// each checked every cycle against a reference queue.

`define CHECK(cond, msg) begin if (cond) passed = passed + 1; else begin failed = failed + 1; $error msg; end end

module sync_fifo_tb;
    localparam integer DA   = 8;
    localparam integer WA   = 8;
    localparam integer DB   = 5;
    localparam integer WB   = 12;
    localparam integer NCOV = 10;
    // Coverage items:
    // 0 reached full            1 write while full     2 drain to empty
    // 3 read while empty        4 wr+rd when empty     5 wr+rd when full
    // 6 wr+rd in between        7 write pointer wrap   8 read pointer wrap
    // 9 reset during traffic

    reg        clk     = 1'b0;
    reg        rst_n   = 1'b0;
    reg        wr_en   = 1'b0;
    reg        rd_en   = 1'b0;
    reg [11:0] wr_data = 12'd0;

    wire          full_a, empty_a;
    wire [WA-1:0] rd_data_a;
    wire [3:0]    count_a;
    wire          full_b, empty_b;
    wire [WB-1:0] rd_data_b;
    wire [2:0]    count_b;

    sync_fifo #(.DEPTH(DA), .WIDTH(WA)) dut_a (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data[WA-1:0]), .full(full_a),
        .rd_en(rd_en), .rd_data(rd_data_a), .empty(empty_a),
        .count(count_a)
    );

    sync_fifo #(.DEPTH(DB), .WIDTH(WB)) dut_b (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data), .full(full_b),
        .rd_en(rd_en), .rd_data(rd_data_b), .empty(empty_b),
        .count(count_b)
    );

    always #5 clk = ~clk;

    // Reference models
    reg [WA-1:0] qa [0:DA-1];
    reg [WB-1:0] qb [0:DB-1];
    integer ha, ca, ta;
    integer hb, cb, tb;
    reg     wa, ra, wb, rb;
    reg     started;
    integer cov_a [0:NCOV-1];
    integer cov_b [0:NCOV-1];
    integer passed, failed, i;
    integer nonce_ok;
    reg [31:0]     rng;
    reg [7:0]      wbias, rbias;
    reg [8*64-1:0] nonce;

    task next_rng;
        begin
            rng = rng ^ (rng << 13);
            rng = rng ^ (rng >> 17);
            rng = rng ^ (rng << 5);
        end
    endtask

    // Change inputs on the falling edge; DUT and model sample on the rising edge.
    task drive(input w, input r, input rs);
        begin
            @(negedge clk);
            next_rng;
            wr_en   = w;
            rd_en   = r;
            rst_n   = rs;
            wr_data = rng[11:0];
        end
    endtask

    // Model update on the rising edge, from the pre-edge model state.
    always @(posedge clk) begin
        if (!rst_n) begin
            if (ca > 0) cov_a[9] = cov_a[9] + 1;
            if (cb > 0) cov_b[9] = cov_b[9] + 1;
            ha = 0; ca = 0;
            hb = 0; cb = 0;
            started = 1'b1;
        end else begin
            // DEPTH 8 model
            wa = wr_en && (ca < DA);
            ra = rd_en && (ca > 0);
            ta = (ha + ca) % DA;
            if (wr_en && ca == DA)            cov_a[1] = cov_a[1] + 1;
            if (rd_en && ca == 0)             cov_a[3] = cov_a[3] + 1;
            if (wr_en && rd_en && ca == 0)    cov_a[4] = cov_a[4] + 1;
            if (wr_en && rd_en && ca == DA)   cov_a[5] = cov_a[5] + 1;
            if (wr_en && rd_en && ca > 0 && ca < DA) cov_a[6] = cov_a[6] + 1;
            if (ra && ca == 1)                cov_a[2] = cov_a[2] + 1;
            if (wa && ta == DA-1)             cov_a[7] = cov_a[7] + 1;
            if (ra && ha == DA-1)             cov_a[8] = cov_a[8] + 1;
            if (wa) qa[ta] = wr_data[WA-1:0];
            if (ra) ha = (ha + 1) % DA;
            if (wa && !ra) ca = ca + 1;
            else if (ra && !wa) ca = ca - 1;
            if (ca == DA) cov_a[0] = cov_a[0] + 1;

            // DEPTH 5 model
            wb = wr_en && (cb < DB);
            rb = rd_en && (cb > 0);
            tb = (hb + cb) % DB;
            if (wr_en && cb == DB)            cov_b[1] = cov_b[1] + 1;
            if (rd_en && cb == 0)             cov_b[3] = cov_b[3] + 1;
            if (wr_en && rd_en && cb == 0)    cov_b[4] = cov_b[4] + 1;
            if (wr_en && rd_en && cb == DB)   cov_b[5] = cov_b[5] + 1;
            if (wr_en && rd_en && cb > 0 && cb < DB) cov_b[6] = cov_b[6] + 1;
            if (rb && cb == 1)                cov_b[2] = cov_b[2] + 1;
            if (wb && tb == DB-1)             cov_b[7] = cov_b[7] + 1;
            if (rb && hb == DB-1)             cov_b[8] = cov_b[8] + 1;
            if (wb) qb[tb] = wr_data;
            if (rb) hb = (hb + 1) % DB;
            if (wb && !rb) cb = cb + 1;
            else if (rb && !wb) cb = cb - 1;
            if (cb == DB) cov_b[0] = cov_b[0] + 1;
        end
    end

    // Every-cycle checks, mid-cycle (outputs depend only on registered state).
    always @(negedge clk) begin
        if (started) begin
            `CHECK(full_a === (ca == DA), ("A full mismatch at %0t: dut=%b model count=%0d", $time, full_a, ca))
            `CHECK(empty_a === (ca == 0), ("A empty mismatch at %0t: dut=%b model count=%0d", $time, empty_a, ca))
            `CHECK(count_a === ca[3:0], ("A count mismatch at %0t: dut=%0d model=%0d", $time, count_a, ca))
            if (ca > 0) begin
                `CHECK(rd_data_a === qa[ha], ("A rd_data mismatch at %0t: dut=%h model=%h", $time, rd_data_a, qa[ha]))
            end
            `CHECK(full_b === (cb == DB), ("B full mismatch at %0t: dut=%b model count=%0d", $time, full_b, cb))
            `CHECK(empty_b === (cb == 0), ("B empty mismatch at %0t: dut=%b model count=%0d", $time, empty_b, cb))
            `CHECK(count_b === cb[2:0], ("B count mismatch at %0t: dut=%0d model=%0d", $time, count_b, cb))
            if (cb > 0) begin
                `CHECK(rd_data_b === qb[hb], ("B rd_data mismatch at %0t: dut=%h model=%h", $time, rd_data_b, qb[hb]))
            end
        end
    end

    initial begin
        passed = 0; failed = 0; started = 1'b0;
        ha = 0; ca = 0; ta = 0; hb = 0; cb = 0; tb = 0;
        wa = 1'b0; ra = 1'b0; wb = 1'b0; rb = 1'b0;
        rng = 32'h1234_5678; wbias = 8'd128; rbias = 8'd128;
        nonce = 0; nonce_ok = 0;
        for (i = 0; i < NCOV; i = i + 1) begin
            cov_a[i] = 0;
            cov_b[i] = 0;
        end

        // Reset
        drive(0, 0, 0); drive(0, 0, 0); drive(0, 0, 0);
        // Read while empty
        drive(0, 1, 1); drive(0, 1, 1);
        // Write and read together when empty
        drive(1, 1, 1);
        // Fill to full, then write while full
        repeat (10) drive(1, 0, 1);
        // Write and read together when full
        repeat (2) drive(1, 1, 1);
        // Drain to empty, then read while empty
        repeat (10) drive(0, 1, 1);
        // Write and read together in between
        repeat (3) drive(1, 0, 1);
        repeat (5) drive(1, 1, 1);
        repeat (4) drive(0, 1, 1);
        // Random traffic with changing write/read bias and rare resets
        for (i = 0; i < 4000; i = i + 1) begin
            if (i % 200 == 0) begin
                next_rng;
                wbias = rng[7:0];
                rbias = rng[15:8];
            end
            next_rng;
            drive(rng[7:0] < wbias, rng[15:8] < rbias, rng[31:22] != 10'd0);
        end
        // Reset during traffic
        drive(0, 0, 0);
        repeat (4) drive(1, 0, 1);
        repeat (2) drive(1, 1, 0);
        // Refill and drain after reset
        repeat (6) drive(1, 0, 1);
        repeat (8) drive(0, 1, 1);
        drive(0, 0, 1);
        @(negedge clk);
        #1;

        // Coverage: every corner case must have been reached
        for (i = 0; i < NCOV; i = i + 1) begin
            `CHECK(cov_a[i] > 0, ("coverage item %0d not reached on the DEPTH %0d FIFO", i, DA))
            `CHECK(cov_b[i] > 0, ("coverage item %0d not reached on the DEPTH %0d FIFO", i, DB))
        end

        nonce_ok = $value$plusargs("nirmaan_nonce=%s", nonce);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
